import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

// Direct 2D convolution (NCHW, contiguous, float32).
// One thread per output element; loops over (ic, kh, kw) with bounds checks.
.visible .entry conv2d_kernel(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 has_bias,
    .param .u32 total,
    .param .u32 OC,
    .param .u32 OH,
    .param .u32 OW,
    .param .u32 IC,
    .param .u32 H,
    .param .u32 W,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w
)
{
    .reg .pred %p<16>;
    .reg .b32  %r<48>;
    .reg .b64  %rd<24>;
    .reg .f32  %f<8>;

    // tid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32  %r0, %ctaid.x;
    mov.u32  %r1, %ntid.x;
    mov.u32  %r2, %tid.x;
    mad.lo.u32 %r3, %r0, %r1, %r2;          // %r3 = tid

    ld.param.u32 %r4, [total];
    setp.ge.u32  %p0, %r3, %r4;
    @%p0 bra DONE;

    // Decompose flat tid -> (b, oc, oh, ow), NCHW contiguous layout.
    ld.param.u32 %r5, [OW];
    rem.u32 %r6, %r3, %r5;                  // %r6 = ow
    div.u32 %r7, %r3, %r5;
    ld.param.u32 %r8, [OH];
    rem.u32 %r9, %r7, %r8;                  // %r9 = oh
    div.u32 %r10, %r7, %r8;
    ld.param.u32 %r11, [OC];
    rem.u32 %r12, %r10, %r11;               // %r12 = oc
    div.u32 %r13, %r10, %r11;               // %r13 = b

    mov.f32 %f0, 0f00000000;                // acc = 0.0f

    mov.u32 %r14, 0;                        // ic = 0
    ld.param.u32 %r15, [IC];
LOOP_IC:
    setp.ge.u32 %p1, %r14, %r15;
    @%p1 bra STORE;

    mov.u32 %r16, 0;                        // kh = 0
    ld.param.u32 %r17, [KH];
LOOP_KH:
    setp.ge.u32 %p2, %r16, %r17;
    @%p2 bra NEXT_IC;

    // ih = oh * stride_h - pad_h + kh * dil_h  (signed)
    ld.param.u32 %r18, [stride_h];
    mul.lo.s32  %r19, %r9, %r18;
    ld.param.u32 %r20, [pad_h];
    sub.s32     %r19, %r19, %r20;
    ld.param.u32 %r21, [dil_h];
    mad.lo.s32  %r19, %r16, %r21, %r19;     // %r19 = ih

    setp.lt.s32 %p3, %r19, 0;
    @%p3 bra NEXT_KH;
    ld.param.u32 %r22, [H];
    setp.ge.s32 %p4, %r19, %r22;
    @%p4 bra NEXT_KH;

    mov.u32 %r23, 0;                        // kw = 0
    ld.param.u32 %r24, [KW];
LOOP_KW:
    setp.ge.u32 %p5, %r23, %r24;
    @%p5 bra NEXT_KH;

    // iw = ow * stride_w - pad_w + kw * dil_w  (signed)
    ld.param.u32 %r25, [stride_w];
    mul.lo.s32  %r26, %r6, %r25;
    ld.param.u32 %r27, [pad_w];
    sub.s32     %r26, %r26, %r27;
    ld.param.u32 %r28, [dil_w];
    mad.lo.s32  %r26, %r23, %r28, %r26;     // %r26 = iw

    setp.lt.s32 %p6, %r26, 0;
    @%p6 bra NEXT_KW;
    ld.param.u32 %r29, [W];
    setp.ge.s32 %p7, %r26, %r29;
    @%p7 bra NEXT_KW;

    // input index = ((b*IC + ic)*H + ih)*W + iw
    mad.lo.u32 %r30, %r13, %r15, %r14;
    mad.lo.u32 %r30, %r30, %r22, %r19;
    mad.lo.u32 %r30, %r30, %r29, %r26;

    // weight index = ((oc*IC + ic)*KH + kh)*KW + kw
    mad.lo.u32 %r31, %r12, %r15, %r14;
    mad.lo.u32 %r31, %r31, %r17, %r16;
    mad.lo.u32 %r31, %r31, %r24, %r23;

    cvt.u64.u32  %rd0, %r30;
    shl.b64      %rd0, %rd0, 2;
    ld.param.u64 %rd1, [in_ptr];
    add.u64      %rd2, %rd1, %rd0;
    ld.global.f32 %f1, [%rd2];

    cvt.u64.u32  %rd3, %r31;
    shl.b64      %rd3, %rd3, 2;
    ld.param.u64 %rd4, [wt_ptr];
    add.u64      %rd5, %rd4, %rd3;
    ld.global.f32 %f2, [%rd5];

    fma.rn.f32 %f0, %f1, %f2, %f0;

NEXT_KW:
    add.u32 %r23, %r23, 1;
    bra LOOP_KW;
NEXT_KH:
    add.u32 %r16, %r16, 1;
    bra LOOP_KH;
NEXT_IC:
    add.u32 %r14, %r14, 1;
    bra LOOP_IC;

STORE:
    ld.param.u32 %r32, [has_bias];
    setp.eq.u32  %p8, %r32, 0;
    @%p8 bra WRITE;
    cvt.u64.u32  %rd9, %r12;                // oc
    shl.b64      %rd9, %rd9, 2;
    ld.param.u64 %rd10, [bias_ptr];
    add.u64      %rd11, %rd10, %rd9;
    ld.global.f32 %f3, [%rd11];
    add.f32      %f0, %f0, %f3;
WRITE:
    cvt.u64.u32  %rd12, %r3;
    shl.b64      %rd12, %rd12, 2;
    ld.param.u64 %rd13, [out_ptr];
    add.u64      %rd14, %rd13, %rd12;
    st.global.f32 [%rd14], %f0;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size,
                                stride=stride, padding=padding,
                                dilation=dilation, bias=bias)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = (kernel_size[0], kernel_size[1])
        self.stride = (stride, stride) if isinstance(stride, int) else (stride[0], stride[1])
        self.padding = (padding, padding) if isinstance(padding, int) else (padding[0], padding[1])
        self.dilation = (dilation, dilation) if isinstance(dilation, int) else (dilation[0], dilation[1])

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()

        B, IC, H, W = x.shape
        OC = self.conv2d.weight.shape[0]
        KH, KW = self.kernel_size
        sh, sw = self.stride
        ph, pw = self.padding
        dh, dw = self.dilation

        OH = (H + 2 * ph - dh * (KH - 1) - 1) // sh + 1
        OW = (W + 2 * pw - dw * (KW - 1) - 1) // sw + 1

        out = torch.empty((B, OC, OH, OW), device=x.device, dtype=x.dtype)
        total = out.numel()

        has_bias = 1 if self.conv2d.bias is not None else 0
        bias_tensor = self.conv2d.bias if self.conv2d.bias is not None else self.conv2d.weight

        threads = 256
        grid_x = (total + threads - 1) // threads

        module.launch(
            "conv2d_kernel",
            grid=(grid_x, 1, 1),
            block=(threads, 1, 1),
            arguments=[
                x,
                self.conv2d.weight,
                bias_tensor,
                out,
                i32(has_bias),
                i32(total),
                i32(OC),
                i32(OH),
                i32(OW),
                i32(IC),
                i32(H),
                i32(W),
                i32(KH),
                i32(KW),
                i32(sh),
                i32(sw),
                i32(ph),
                i32(pw),
                i32(dh),
                i32(dw),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

