        B, IC, H, W = x.shape
        OC = self.conv2d.weight.shape[0]
        KH, KW = self.kernel_size
        sh, sw = self.stride
        ph, pw = self.padding
        dh, dw = self.dilation

        OH = (H + 2 * ph - dh * (KH - 1) - 1) // sh + 1
        OW = (W + 2 * pw - dw * (KW - 1) - 1) // sw + 1

        out = torch.empty((B, OC, OH, OW), device=x.device, dtype=x.dtype)
        total = out.numel()

