        bias_tensor = self.conv2d.bias if self.conv2d.bias is not None else self.conv2d.weight

        threads = 256
        grid_x = (total + threads - 1) // threads

        module.launch(
            "conv2d_kernel",
            grid=(grid_x, 1, 1),
            block=(threads, 1, 1),
            arguments=[
                x,
                self.conv2d.weight,
                bias_tensor,
                out,
                i32(has_bias),
                i32(total),
                i32(OC),
                i32(OH),
                i32(OW),
                i32(IC),
                i32(H),
                i32(W),
                i32(KH),
                i32(KW),
                i32(sh),
                i32(sw),
                i32(ph),
                i32(pw),
                i32(dh),
                i32(dw),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
